const buildCountHostServicesFromTemplateQuery = (
  hostName: string,
  serviceTemplate: string
): string =>
  'SELECT COUNT(*) AS total FROM host_service_relation hsr ' +
  'JOIN host h ON h.host_id = hsr.host_host_id ' +
  'JOIN service s ON s.service_id = hsr.service_service_id ' +
  'JOIN service st ON st.service_id = s.service_template_model_stm_id ' +
  `WHERE h.host_name = '${hostName}' ` +
  `AND st.service_description = '${serviceTemplate}'`;

// Engine files generated by Centreon for a poller
const buildGeneratedHostsFile = (pollerId: number): string =>
  `/var/cache/centreon/config/engine/${pollerId}/hosts.cfg`;

const generatedHostsFile = buildGeneratedHostsFile(1);

const buildHostNameByIdQuery = (hostId: number): string =>
  `SELECT host_name FROM host WHERE host_id = ${hostId}`;

const buildHostCountByNamePrefixQuery = (prefix: string): string =>
  `SELECT COUNT(*) AS count FROM host WHERE host_name LIKE '${prefix}%'`;

const buildCentralPollerIdQuery = (): string =>
  "SELECT id FROM nagios_server WHERE localhost = '1' ORDER BY id LIMIT 1";

// Services of a host created from a service template, with their description
const buildHostServicesFromTemplateQuery = (
  hostName: string,
  serviceTemplate: string
): string =>
  'SELECT s.service_description AS description FROM host_service_relation hsr ' +
  'JOIN host h ON h.host_id = hsr.host_host_id ' +
  'JOIN service s ON s.service_id = hsr.service_service_id ' +
  'JOIN service st ON st.service_id = s.service_template_model_stm_id ' +
  `WHERE h.host_name = '${hostName}' ` +
  `AND st.service_description = '${serviceTemplate}'`;

// "Contacts & Contact groups method calculation" of Administration > Parameters
const cumulativeInheritanceMode = 3;

const buildSetInheritanceModeQuery = (mode: number): string =>
  `UPDATE options SET value = '${mode}' WHERE \`key\` = 'inheritance_mode'`;

const buildRealTimeCheckIntervalQuery = (hostName: string): string =>
  `SELECT check_interval FROM hosts WHERE name = '${hostName}' AND enabled = 1`;

// Resources (the host and its services) Resources Status still lists
const buildEnabledResourcesOfHostQuery = (hostName: string): string =>
  'SELECT COUNT(*) AS count FROM resources ' +
  'WHERE enabled = 1 AND (' +
  `(type = 1 AND name = '${hostName}') OR (type = 0 AND parent_name = '${hostName}'))`;

// Blocks of the "define host" objects of an Engine hosts file
const hostDefinitions = (hostsFile: string): Array<string> =>
  hostsFile.split(/define host\s*\{/).slice(1);

// Type of every object an Engine file defines ("host", "command"...)
const definedObjectTypes = (file: string): Array<string> =>
  [...file.matchAll(/^\s*define\s+(\w+)/gm)].map(([, type]) => type);

// Value of an attribute of each "define host" block, in file order
const hostAttributeValues = (
  hostsFile: string,
  attribute: string
): Array<string> =>
  hostDefinitions(hostsFile)
    .map((block) =>
      block
        .split('\n')
        .map((line) => line.trim())
        .find((line) => new RegExp(`^${attribute}\\s`).test(line))
    )
    .filter((line): line is string => line !== undefined)
    .map((line) => line.replace(new RegExp(`^${attribute}\\s+`), '').trim());

// Value of an attribute in the definition of one host, null if absent
const hostAttributeValue = (
  hostsFile: string,
  hostName: string,
  attribute: string
): string | null => {
  const definition = hostDefinitions(hostsFile).find((block) =>
    block
      .split('\n')
      .some(
        (line) => line.trim().replace(/\s+/, ' ') === `host_name ${hostName}`
      )
  );
  const line = definition
    ?.split('\n')
    .map((row) => row.trim())
    .find((row) => new RegExp(`^${attribute}\\s`).test(row));

  return line ? line.replace(new RegExp(`^${attribute}\\s+`), '').trim() : null;
};

export {
  buildCentralPollerIdQuery,
  buildCountHostServicesFromTemplateQuery,
  buildEnabledResourcesOfHostQuery,
  buildGeneratedHostsFile,
  buildHostCountByNamePrefixQuery,
  buildHostNameByIdQuery,
  buildHostServicesFromTemplateQuery,
  buildRealTimeCheckIntervalQuery,
  buildSetInheritanceModeQuery,
  cumulativeInheritanceMode,
  definedObjectTypes,
  generatedHostsFile,
  hostAttributeValue,
  hostAttributeValues,
  hostDefinitions
};
